Method.Implementation:
 // Web Service Method Implementation Goes Here.
 //set request = ##class(SoapRequestMessage).%New()
 //set request.PayloadID=PayloadID
 $$$TRACE("PayloadID :  " _PayloadID _ ", CORERuleVersion: " _CORERuleVersion)

 // Web Service Method Implementation Goes Here.
 //set request = ##class(SoapRequestMessage).%New()
 //set request.PayloadID=PayloadID

 // Send to trans tracking
 Set tSC= $$$OK
 set bas64Enc = 0

 set x12Data = Payload
 IF ($EXTRACT(Payload,1,3) '= "ISA")
 {
	 try {
		 $$$TRACE("Call Base64Decode")
 		 set x12Data = $system.Encryption.Base64Decode(Payload)
 		 set bas64Enc = 1
	 } catch err
	 {
		 $$$TRACE("Not a base 64 string")
	 }
 	if ($L(x12Data) = 0)
 	{
	 	set x12Data = Payload
 	}
 }
 // $$$TRACE("27x Data: " _ x12Data)
 //set request.ProcessingMode=ProcessingMode
 set x12MsgReq = ##class(IHC.ITF.Request.x12MessageReq).%New()

 #dim pDocIn As EnsLib.EDI.X12.Document
 set pDocIn = ##class(EnsLib.EDI.X12.Document).ImportFromString(x12Data)
 if ( ($ISOBJECT(pDocIn)) && (pDocIn.%Extends("EnsLib.EDI.X12.Document")) )
 {

	 if ($GET(^ItfGlobalX12Core(..%ConfigName)) = "")
	 {
		 // $$$TRACE("Create global")
		 set ^ItfGlobalX12Core(..%ConfigName) = 0
	 }
	 set ^ItfGlobalX12Core(..%ConfigName) = ^ItfGlobalX12Core(..%ConfigName) + 1

	 set pDocIn.OriginalDocId = $GET(^ItfGlobalX12Core(..%ConfigName))

	 $$$TRACE(pDocIn.OriginalDocId _". X12 data: " _ pDocIn.FullSizeGet() _", "_ pDocIn.TypeVersion)

	  set pDocIn.DocType = "HIPAA_5010:Interchange:Group"

		   Set tSC =pDocIn.BuildMap()		   
		   set x12MsgReq.ControlNumber = pDocIn.GetValueAt("ISA:InterchangeControlNumber")
		   set x12MsgReq.SenderID = $ZSTRIP(pDocIn.GetValueAt("ISA:InterchangeSenderID"), "<>W")
		   set x12MsgReq.ReceiverID = $ZSTRIP(pDocIn.GetValueAt("ISA:InterchangeReceiverID"), "<>W")

	   if ( (x12MsgReq.SenderID ="") ||  (x12MsgReq.ReceiverID = "") )
	   {
		   set fullErrorMsg = "Interchange values are empty, Invalid X12: " _ pDocIn.OutputToString()
		   $$$TRACE(fullErrorMsg)
		   QUIT $$$ERROR($$$EnsErrGeneral, "Invalid X12: " _ fullErrorMsg)
	   }
	   set tranType = pDocIn.FunctionalGroups(1).TransactionSets(1).GetValueAt("1:1")
	   // $$$TRACE(tranType _", IDs: " _ x12MsgReq.SenderID _" -> " _ x12MsgReq.ReceiverID)

	   //Use clean data
	   set x12Doc = pDocIn.OutputToString()
	   set pDocIn = ##class(EnsLib.EDI.X12.Document).ImportFromString(x12Doc, .stat)

	   if (tranType = 276)
		{
	   		set pDocIn.DocType = "HIPAA_5010:Interchange:Group:276"
		}
		else
		{
			set pDocIn.DocType = "HIPAA_5010:Interchange:Group:270"
		}
		/*
		EnsLib.EDI.X12.Util.Validator
		'd' - require DocType
		'l' - enforce field/component length restrictions
		'm' - don't tolerate BuildMap segment mapping errors
		's' - enforce segment structures (number and repetition of fields)
		*/
		set stat = ##class(EnsLib.EDI.X12.Util.Validator).Validate(pDocIn, "dmls")
		if ( $$$ISERR(stat) )
	    {
		   set fullErrorMsg = "X12 validation failed, Invalid X12" 
		   Do DecomposeStatus^%apiOBJ(stat,.err,"-d") 

		     set errMsg = $system.Status.GetErrorText(stat)
		     $$$TRACE(errMsg)
			 For i=1:1:err
			 { 
			  	set fullErrorMsg = fullErrorMsg _ ", Error: " _ err(i) 
			  	set PayloadType = "Error"

			  	if errMsg [ "HIPAA_5010:Interchange"
			  	{
			  	    set fldInd = $FIND(errMsg, "ISA.  Field ")
			  	    set fldNum = $ZSTRIP($EXTRACT(errMsg,fldInd, $FIND(errMsg, " ", fldInd)-1), "*W")
			  	    $$$TRACE("Invalid Fld # " _ fldNum)
			  	    set TA105 = $LISTBUILD("010","011","012","013","005","006","007","008","014","015","","","018","019","020", "026")

			  	    set context = ##class(%DynamicObject).%New()
   					set v = $LISTDATA(TA105,fldNum, val)

					set context.IsaErrorField = val		

					 set sc=##class(IHC.ITF.CORERULES.Service.CR27xToTA1).Transform(pDocIn,.target, .context)
					 if $$$ISERR(sc)
					  {
						  set Payload = "Error in generating TA1: " _ $system.Status.GetErrorText(sc)

					  }
					  else
					  {
				  		set Payload = target.OutputToString()	
					  }						  				 	
				  		Set ErrorCode="1"
				 		Set ErrorMessage= fullErrorMsg
				 		set al = ##class(Ens.AlertRequest).%New()
				 		// ITFCOMMONInvalidDataError "ITFCOMMON:10108"
				 		set al.AlertText = "ITFCOMMON:10108: " _ fullErrorMsg
				 		set al.SourceConfigName = ..%ConfigName
				 		Do ..SendAlert(al)
				 		QUIT

				 }

				 else
				 {
				 	set stat = $$$OK
				 	// Let Edifecs generate 999
				 }

			 }


	    }
	    if ( $$$ISERR(stat) )
	    {
		    QUIT $$$ERROR($$$EnsErrGeneral, "Invalid ISA in X12: " _ fullErrorMsg)
	    }

	   set dtTm = $HOROLOG
	   set randNum = $RANDOM(999)
	   set x12MsgReq.TtDataSource = ..%ConfigName
	   set x12MsgReq.TimeStamp = $ZDATETIME(dtTm, 3,1)
	   set x12MsgReq.TtUniqueId = $REPLACE(dtTm, ",", "") _ randNum _ x12MsgReq.ControlNumber
	   set x12MsgReq.PayloadType = ProcessingMode
	   set x12MsgReq.TtMsgType= tranType
	   set x12MsgReq.Payload = x12Doc

		set x12MsgReq.strTtBatchReal = "Y"
		set x12MsgReq.pCLCLID = ""

		set x12MsgReq.ReceiverID = "UHIN"
		set TimeStamp = $REPLACE(x12MsgReq.TimeStamp," ", "T")

		set SenderID = x12MsgReq.ReceiverID

		if (tranType = 276)
		{
		    set x12MsgReq.pSBSBID = pDocIn.FunctionalGroups(1).TransactionSets(1).GetValueAt("loop2000A(1).loop2000B(1).loop2000C(1).loop2000D(1).loop2100D.NM1:9")

			if (pDocIn.FunctionalGroups(1).TransactionSets(1).GetValueAt("loop2000A(1).loop2000B(1).loop2000C(1).loop2000D(1).loop2200D(1).REF(1):RefIdQualifier") = "1K")
			{
				set x12MsgReq.pCLCLID = pDocIn.FunctionalGroups(1).TransactionSets(1).GetValueAt("loop2000A(1).loop2000B(1).loop2000C(1).loop2000D(1).loop2200D(1).REF(1):RefId")
			}
			elseif (pDocIn.FunctionalGroups(1).TransactionSets(1).GetValueAt("loop2000A(1).loop2000B(1).loop2000C(1).loop2000D(1).loop2000E(1).loop2200E(1).REF(1):RefIdQualifier") = "1K")
			{
				set x12MsgReq.pCLCLID = pDocIn.FunctionalGroups(1).TransactionSets(1).GetValueAt("loop2000A(1).loop2000B(1).loop2000C(1).loop2000D(1).loop2000E(1).loop2200E(1).REF(1):RefId")
			}
			else
			{
				$$$TRACE("pCLCLID: is null")
			}
			// "EDI_CORE"."SH_EDI_TRANSACTION_LOG"."SBSB_ID" maximum: 9
			if ($L(x12MsgReq.pSBSBID) > 9)
			{
					 set x12MsgReq.pSBSBID = $EXTRACT(x12MsgReq.pSBSBID, 1, 9)
			}

			// "EDI_CORE"."SH_EDI_TRANSACTION_LOG"."CLCL_ID" maximum: 12
			if ($L(x12MsgReq.pCLCLID) > 12)
			{
					 set x12MsgReq.pCLCLID = $EXTRACT(x12MsgReq.pCLCLID, 1, 12)
			}

			$$$TRACE(tranType _ " pSBSBID: " _ x12MsgReq.pSBSBID _ ", pCLCLID: " _ x12MsgReq.pCLCLID)

			 For iTarget=1:1:$L(..Edifecs276TargetConfigNames,",") 
			 { 
			 	Set tOneTarget=$ZStrip($P(..Edifecs276TargetConfigNames,",",iTarget),"<>W")  Continue:""=tOneTarget
				$$$TRACE("Sending X12 document to '"_tOneTarget_"'")
				try
				{
					Set tSC=..SendRequestSync(tOneTarget,x12MsgReq,.tResponse)

					set PayloadType = "X12_277_Response_005010X212"					
				}
				catch err {
					Set ErrorMessage =err.Data
					set x12MsgReq.RespPayload = "Error in generating 277"
					set tSC = $$$ERROR("Exception in calling the operation: " _ err.Data)
				}
			 	// Send to trans tracking
			 }
		}
		else // 270
		{
			 set x12MsgReq.pSBSBID = pDocIn.FunctionalGroups(1).TransactionSets(1).GetValueAt("loop2000A(1).loop2000B(1).loop2000C(1).loop2100C.NM1:9")
			 // "EDI_CORE"."SH_EDI_TRANSACTION_LOG"."SBSB_ID" maximum: 9
			 if ($L(x12MsgReq.pSBSBID) > 9)
			 {
				 set x12MsgReq.pSBSBID = $EXTRACT(x12MsgReq.pSBSBID, 1, 9)
			 }


			 For iTarget=1:1:$L(..Edifecs270TargetConfigNames,",") 
			 { 
			 	Set tOneTarget=$ZStrip($P(..Edifecs270TargetConfigNames,",",iTarget),"<>W")  Continue:""=tOneTarget
				$$$TRACE(tranType _ " Sending X12 document to '"_tOneTarget_"'")
				try
				{
					Set tSC=..SendRequestSync(tOneTarget,x12MsgReq,.tResponse)
					$$$TRACE("SendRequestSync stat: " _ tSC)
					set PayloadType = "X12_271_Response_005010X279A1" 
				}
				catch err {
					Set ErrorMessage =err.Data
					set x12MsgReq.RespPayload = "Error in generating 271"
					Set ErrorCode="500"
					set tSC = $$$ERROR("Exception in calling the operation: " _ err.Data)
				}

			 }
	 	}

	 	// Received data form the operation with 271/277 response
	 	if ($$$ISOK(tSC))
	 	{
		 	set regexp = ".*(ERROR|TIMEOUT).*"
		 	if ( ($L(tResponse.StringValue) < 1) || ($MATCH($ZCONVERT(tResponse.StringValue,"U"), regexp) = 1) )
		 	{
			 	$$$TRACE("Empty Response or error")
			 	Set ErrorCode="500"
		 		Set ErrorMessage= tSC
		 		set al = ##class(Ens.AlertRequest).%New()
		 		// ITFCOMMONInvalidDataError "ITFCOMMON:10108"
		 		set al.AlertText = "ITFCOMMON:10108: Response from Edifecs is NULL, TtUniqueId: " _ x12MsgReq.TtUniqueId
		 		set al.SourceConfigName = ..%ConfigName
		 		Do ..SendAlert(al)
		 		set sc=$$$OK
		 		if (tranType = 276)
				{
					set sc=##class(IHC.ITF.CORERULES.Service.CR276To277AAA).Transform(pDocIn,.target, .context)
				}
				else
				{
				 	set sc=##class(IHC.ITF.CORERULES.Service.CR270To271AAA).Transform(pDocIn,.target, .context)
				}
				 if $$$ISERR(sc)
				  {
					  set tResponse.StringValue = "Error in generating AAA: " _ $system.Status.GetErrorText(sc)

				  }
				  else
				  {
			  		set tResponse.StringValue = target.OutputToString()	
				  }						  	 
		 	}

		 	if (bas64Enc = 1)
			{
				// No linefeed
				set Payload = $system.Encryption.Base64Encode(tResponse.StringValue, 1)
			}
			else
			{
				set Payload = tResponse.StringValue
			}
			set x12MsgReq.RespPayload = tResponse.StringValue
			Set ErrorCode="Success"
		 	Set ErrorMessage= ""


		 }
		 else // Error from the Edifecs service
		 {			 
			 	Set ErrorCode="500"
		 		Set ErrorMessage= tSC
		 		set sc=$$$OK
		 		if (tranType = 276)
				{
					set sc=##class(IHC.ITF.CORERULES.Service.CR276To277AAA).Transform(pDocIn,.target, .context)
				}
				else
				{
				 	set sc=##class(IHC.ITF.CORERULES.Service.CR270To271AAA).Transform(pDocIn,.target, .context)
				}

				 if $$$ISERR(sc)
				  {
					  set Payload = "Error in generating AAA: " _ $system.Status.GetErrorText(sc)

				  }
				  else
				  {
			  		set Payload = target.OutputToString()
			  		set x12MsgReq.RespPayload = Payload
			  		Set ErrorCode="Success"
		 			Set ErrorMessage= ""

				  }	

		 		set al = ##class(Ens.AlertRequest).%New()
		 		set al.AlertText = "ERROR " _ $$$EnsErrFailureTimeout _ ": Error in calling Edifecs, " _ tSC _ ", TtUniqueId: " _ x12MsgReq.TtUniqueId
		 		set al.SourceConfigName = ..%ConfigName
		 		set aStat = ..SendAlert(al)
		 		$$$TRACE("SendAlert: " _ aStat)
		 }
	 	set x12MsgReq.pTransactionFileName = x12MsgReq.SenderID _"-" _ x12MsgReq.ReceiverID _"-" _ x12MsgReq.pSBSBID _"-" _ x12MsgReq.TtUniqueId _ "." _ tranType

	 	set x12MsgReq.RespTimeStamp = $ZDATETIME($HOROLOG, 3,1)
	 	// Send to trans tracking
	 	if (tranType = 276)
		{

		  	For iTarget=1:1:$L(..TransTrack276TargetConfigNames,",") 
		 	{ 
		 		Set tOneTarget=$ZStrip($P(..TransTrack276TargetConfigNames,",",iTarget),"<>W")  Continue:""=tOneTarget
				$$$TRACE("Sending Trans tracking data to '"_tOneTarget_"'")

				Set tSC1=..SendRequestAsync(tOneTarget,x12MsgReq,.tResponse)
		 	}
		}
		else 
		{
			For iTarget=1:1:$L(..TransTrack270TargetConfigNames,",") 
		 	{ 
		 		Set tOneTarget=$ZStrip($P(..TransTrack270TargetConfigNames,",",iTarget),"<>W")  Continue:""=tOneTarget
				$$$TRACE("Sending Trans tracking data to '"_tOneTarget_"'")

				Set tSC1=..SendRequestAsync(tOneTarget,x12MsgReq,.tResponse)
		 	}

		}

 	Quit tSC
	}
	else
	{
		   set fullErrorMsg = "X12 validation failed, X12.Document parsing failed: " _ x12Data

		 	Set ErrorCode="500"
	 		Set ErrorMessage= tSC
	 		set al = ##class(Ens.AlertRequest).%New()
	 		// ITFCOMMONInvalidDataError "ITFCOMMON:10108"
	 		set al.AlertText = "ITFCOMMON:10108: " _ fullErrorMsg
	 		set al.SourceConfigName = ..%ConfigName
	 		Do ..SendAlert(al)
	 		QUIT $$$ERROR($$$EnsErrGeneral, "Invalid X12: " _ fullErrorMsg)
	}

Do ##super(.pArray,pItem)

If pItem.GetModifiedSetting("Edifecs270TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") 
	{ 
		Set tOne=$ZStrip($P(tValue,",",i),"<>W")  
		Continue:""=tOne  Set pArray(tOne)="" 
	}
}
If pItem.GetModifiedSetting("Edifecs276TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") 
	{ 
		Set tOne=$ZStrip($P(tValue,",",i),"<>W")  
		Continue:""=tOne  Set pArray(tOne)="" 
	}
}
If pItem.GetModifiedSetting("TransTrack270TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") 
	{ 
		Set tOne=$ZStrip($P(tValue,",",i),"<>W")  
		Continue:""=tOne  Set pArray(tOne)="" 
	}
}
If pItem.GetModifiedSetting("TransTrack276TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") 
	{ 
		Set tOne=$ZStrip($P(tValue,",",i),"<>W")  
		Continue:""=tOne  Set pArray(tOne)="" 
	}
}
